INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (7, "キャル", 0, 0.0, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", 1, 106001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 7001, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (7, "コッコロ", 0, 0.0, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 7002, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (7, "ペコリーヌ", 0, 0.0, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 7003, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (10, "ペコリーヌ", 0, 0.0, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 10001, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (10, "キャル", 0, 0.0, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", 1, 106001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 10002, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (10, "コッコロ", 0, 0.0, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 10003, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (10, "シェフィ", 2104010, 0.0, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", 1, 106401, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 10004, 1, 0.0, -363.0, 0, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (12, "ペコリーヌ", 0, 0.0, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 12001, 1, 0.0, -416.5, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (13, "キャル", 0, 0.0, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", 1, 106001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 13001, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (13, "コッコロ", 0, 0.0, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 13002, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (13, "シェフィ", 2104010, 0.0, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", 1, 106401, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 13003, 1, 0.0, -363.0, 0, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (13, "ペコリーヌ", 0, 0.0, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 13004, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (14, "コッコロ", 0, 0.0, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 14001, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (14, "シェフィ", 2104010, 0.0, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", 1, 106401, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 14002, 1, 0.0, -363.0, 0, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (14, "ペコリーヌ", 0, 0.0, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 14003, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (14, "キャル", 0, 0.0, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", 1, 106001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 14004, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (15, "コッコロ", 0, 0.0, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 15001, 1, 0.0, -470.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (16, "シェフィ", 2104010, 0.0, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", 1, 106401, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 16001, 1, 0.0, -363.0, 0, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (16, "ペコリーヌ", 0, 0.0, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 16002, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (16, "キャル", 0, 0.0, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", 1, 106001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 16003, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (16, "コッコロ", 0, 0.0, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 16004, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (17, "コッコロ", 0, 0.0, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 17002, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (25, "キャル", 0, 0.0, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", 1, 106001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 17004, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (25, "コッコロ", 0, 0.0, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 17005, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (25, "シェフィ", 2104010, 0.0, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", 1, 106401, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 17006, 1, 0.0, -363.0, 0, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (25, "ペコリーヌ", 0, 0.0, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 17007, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (18, "カリン", 0, 0.0, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", 1, 190801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 18001, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (18, "カリン", 0, 0.0, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", 2, 190801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 18002, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (19, "カリン", 0, 0.0, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", 3, 190801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 19001, 1, 0.0, -470.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (19, "カリン", 0, 0.0, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", 4, 190801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 19002, 1, 0.0, -470.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (20, "カリン", 0, 0.0, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", 5, 190801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 20001, 1, 0.0, -470.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (20, "カリン", 0, 0.0, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", 6, 190801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 20002, 1, 0.0, -470.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (21, "キャル", 0, 0.0, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", 1, 106001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 21001, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (21, "コッコロ", 0, 0.0, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 21002, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (21, "シェフィ", 2104010, 0.0, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", 1, 106401, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 21003, 1, 0.0, -363.0, 0, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (21, "ペコリーヌ", 0, 0.0, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 21004, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (22, "カリン", 0, 0.0, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", 1, 190801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 22001, 1, 0.0, -430.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (22, "カリン", 0, 0.0, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", 2, 190801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 22002, 1, 0.0, -430.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (23, "カリン", 0, 0.0, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", 3, 190801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 23001, 1, 0.0, -430.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (23, "カリン", 0, 0.0, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", 4, 190801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 23002, 1, 0.0, -430.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "エリコ（バレンタイン）", 0, 8.0, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", 1, 109001, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24001, 2, 4.08, -385.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "エリコ（バレンタイン）", 0, 8.0, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", 2, 109001, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24002, 2, 5.0, -385.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "エリコ（バレンタイン）", 0, 8.0, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", 3, 109001, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24003, 2, 10.11, -385.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "エリコ（バレンタイン）", 0, 8.0, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", 4, 109001, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24004, 2, 4.0, -385.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "エリコ（バレンタイン）", 0, 8.0, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", 5, 109001, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24005, 2, 6.0, -385.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "エリコ（バレンタイン）", 0, 0.0, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", 6, 109002, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24006, 1, 0.0, 0.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "エリコ（バレンタイン）", 0, 0.0, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", 7, 109002, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24007, 1, 0.0, 0.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "エリコ（バレンタイン）", 0, 0.0, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", 8, 109002, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24008, 1, 0.0, 0.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "エリコ（バレンタイン）", 0, 0.0, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", 9, 109002, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24009, 1, 0.0, 0.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "エリコ（バレンタイン）", 0, 0.0, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", 10, 109002, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24010, 1, 0.0, 0.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "シズル（バレンタイン）", 0, 8.0, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", 1, 109101, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24011, 2, 2.12, -385.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "シズル（バレンタイン）", 0, 8.0, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", 2, 109101, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24012, 2, 4.19, -385.0, 10011, 5);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "シズル（バレンタイン）", 0, 8.0, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", 3, 109101, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24013, 4, 2.3, -385.0, 10011, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "シズル（バレンタイン）", 0, 0.0, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", 4, 109102, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24014, 1, 0.0, 0.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "シズル（バレンタイン）", 0, 8.0, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", 5, 109101, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24015, 2, 5.23, -385.0, 10011, 5);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "シズル（バレンタイン）", 0, 0.0, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", 6, 109102, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24016, 1, 0.0, 0.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "シズル（バレンタイン）", 0, 8.0, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", 7, 109101, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24017, 2, 5.01, -385.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "シズル（バレンタイン）", 0, 0.0, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", 8, 109102, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24018, 1, 0.0, 0.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "シズル（バレンタイン）", 0, 0.0, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", 9, 109102, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24019, 1, 0.0, 0.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (24, "シズル（バレンタイン）", 0, 0.0, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", 10, 109102, "2030/12/17 14:59:59", "2019/01/31 12:00:00", 24020, 1, 0.0, 0.0, 10011, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (26, "シェフィ", 2104010, 0.0, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", 1, 106401, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 26001, 1, 0.0, -363.0, 0, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (26, "ペコリーヌ", 0, 0.0, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 26002, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (26, "キャル", 0, 0.0, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", 1, 106001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 26003, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (26, "コッコロ", 0, 0.0, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 26004, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (27, "シェフィ", 2104010, 0.0, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", 1, 106401, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 27001, 1, 0.0, -363.0, 0, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (27, "ペコリーヌ", 0, 0.0, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 27002, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (27, "キャル", 0, 0.0, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", 1, 106001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 27003, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (27, "コッコロ", 0, 0.0, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 27004, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (28, "カリン", 0, 0.0, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", 1, 190801, "2030/12/17 14:59:59", "2019/09/24 15:00:00", 28001, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (28, "カリン", 0, 0.0, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", 2, 190801, "2030/12/17 14:59:59", "2019/09/24 15:00:00", 28002, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (29, "カリン", 0, 0.0, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", 3, 190801, "2030/12/17 14:59:59", "2019/09/24 15:00:00", 29001, 1, 0.0, -409.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (29, "カリン", 0, 0.0, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", 4, 190801, "2030/12/17 14:59:59", "2019/09/24 15:00:00", 29002, 1, 0.0, -409.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (30, "カリン", 0, 0.0, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", 5, 190801, "2030/12/17 14:59:59", "2019/09/24 15:00:00", 30001, 1, 0.0, -409.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (30, "カリン", 0, 0.0, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", 6, 190801, "2030/12/17 14:59:59", "2019/09/24 15:00:00", 30002, 1, 0.0, -409.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (31, "カリン", 0, 0.0, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", 7, 190801, "2030/12/17 14:59:59", "2019/10/31 12:00:00", 31001, 1, 0.0, -409.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (31, "カリン", 0, 0.0, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", 8, 190801, "2030/12/17 14:59:59", "2019/10/31 12:00:00", 31002, 1, 0.0, -409.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (32, "カリン", 0, 0.0, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", 1, 190801, "2020/01/04 4:59:59", "2019/12/20 5:00:00", 32001, 1, 0.0, -409.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (32, "カリン", 0, 0.0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 2, 190801, "2020/01/04 4:59:59", "2019/12/20 5:00:00", 32002, 1, 0.0, -409.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (33, "カリン", 0, 0.0, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", 3, 190801, "2020/01/04 4:59:59", "2019/12/20 5:00:00", 33001, 1, 0.0, -409.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (33, "カリン", 0, 0.0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 4, 190801, "2020/01/04 4:59:59", "2019/12/20 5:00:00", 33002, 1, 0.0, -409.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (34, "カリン", 0, 0.0, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", 5, 190801, "2020/01/10 11:59:59", "2020/01/04 5:00:00", 34001, 1, 0.0, -409.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (34, "カリン", 0, 0.0, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", 6, 190801, "2020/01/10 11:59:59", "2020/01/04 5:00:00", 34002, 1, 0.0, -409.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (38, "ペコリーヌ", 0, 0.0, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 38001, 2, 5.3, -458.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (38, "ペコリーヌ", 0, 0.0, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", 2, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 38002, 2, 6.5, -458.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (39, "ペコリーヌ", 0, 9999.0, "", 0, 105801, "2020/04/08 23:59:59", "2020/04/01", 39005, 3, 0.0, 9999.0, 0, 3);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (40, "カリン", 0, 0.0, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", 2, 190801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 40001, 1, 0.0, -430.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (41, "シェフィ", 2104010, 0.0, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", 1, 106401, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 41001, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (41, "ペコリーヌ", 0, 0.0, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 41002, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (41, "キャル", 0, 0.0, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", 1, 106001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 41003, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (41, "コッコロ", 0, 0.0, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 41004, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (42, "コッコロ", 0, 0.0, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 42001, 1, 0.0, -416.5, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (42, "シェフィ", 2104010, 0.0, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", 1, 106401, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 42002, 1, 0.0, -416.5, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (42, "ペコリーヌ", 0, 0.0, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 42003, 1, 0.0, -416.5, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (42, "キャル", 0, 0.0, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", 1, 106001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 42004, 1, 0.0, -416.5, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (43, "ペコリーヌ", 0, 0.0, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", 1, 105801, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 43001, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (43, "コッコロ", 0, 0.0, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", 1, 105901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 43002, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (43, "キャル", 0, 0.0, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", 1, 106001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 43003, 1, 0.0, -363.0, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (44, "アメス", 0, 0.0, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", 1, 123001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 43004, 1, 0.0, -416.5, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (44, "アメス", 0, 0.0, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", 2, 123001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 43005, 1, 0.0, -416.5, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (45, "アメス", 0, 0.0, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", 3, 123001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 43006, 2, 5.79, -416.5, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (46, "アメス", 0, 0.0, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", 1, 123001, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 46001, 1, 0.0, -371.5, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (47, "シズル", 0, 0.0, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", 1, 104901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 47001, 2, 0.0, -416.5, 0, 2);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (47, "リノ", 0, 0.0, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", 1, 101101, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 47002, 2, 9.32, -416.5, 0, 1);
INSERT INTO `v1_90ee2297c400a5adbf35c2a72cbea5d5ee0f6e6a4e852e7247afc8dbb4427937` VALUES (48, "シズル", 0, 0.0, "", 0, 104901, "2030/12/17 14:59:59", "2015/12/17 15:00:00", 48001, 2, 0.0, -470.0, 0, 2);
